'use client'

import { useCallback, useRef, useEffect, useState } from 'react'
import { useRouter, useSearchParams, usePathname } from 'next/navigation'
import { ChevronDown, X } from 'lucide-react'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import { Checkbox } from '@/components/ui/checkbox'
import { Button } from '@/components/ui/button'
import { AppointmentStatusBadge } from './AppointmentStatusBadge'
import { cn } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type BookingStatus = Database['public']['Tables']['bookings']['Row']['status']

export interface FilterBarState {
  dateShortcut: 'today' | 'this_week' | ''
  artistIds: string[]
  statuses: BookingStatus[]
  hasDeposit: boolean
}

interface Artist {
  id: string
  display_name: string
}

interface AppointmentFilterBarProps {
  artists: Artist[]
  value: FilterBarState
  onChange: (next: FilterBarState) => void
}

const ALL_STATUSES: BookingStatus[] = [
  'pending',
  'confirmed',
  'in_progress',
  'completed',
  'cancelled',
  'no_show',
]

function Chip({
  active,
  children,
  onClick,
  hasPopover,
  'aria-pressed': ariaPressed,
  'aria-expanded': ariaExpanded,
  'aria-haspopup': ariaHasPopup,
}: {
  active: boolean
  children: React.ReactNode
  onClick?: () => void
  hasPopover?: boolean
  'aria-pressed'?: boolean
  'aria-expanded'?: boolean
  'aria-haspopup'?: 'listbox' | 'dialog' | 'menu' | 'true' | 'false'
}) {
  return (
    <button
      type="button"
      role="button"
      aria-pressed={ariaPressed}
      aria-expanded={ariaExpanded}
      aria-haspopup={ariaHasPopup}
      onClick={onClick}
      className={cn(
        'inline-flex items-center gap-1 rounded-full px-3 py-1 text-xs font-medium shrink-0 transition-colors duration-100',
        active
          ? 'bg-primary text-primary-foreground'
          : 'bg-background border border-border text-muted-foreground hover:bg-muted/60',
      )}
    >
      {children}
      {hasPopover && (
        <ChevronDown
          className={cn('h-3 w-3 ml-0.5 transition-transform duration-100', active && 'opacity-80')}
          aria-hidden="true"
        />
      )}
    </button>
  )
}

export function AppointmentFilterBar({
  artists,
  value,
  onChange,
}: AppointmentFilterBarProps) {
  const [artistPopoverOpen, setArtistPopoverOpen] = useState(false)
  const [statusPopoverOpen, setStatusPopoverOpen] = useState(false)

  const setDateShortcut = useCallback(
    (shortcut: 'today' | 'this_week') => {
      onChange({
        ...value,
        dateShortcut: value.dateShortcut === shortcut ? '' : shortcut,
      })
    },
    [value, onChange],
  )

  const toggleArtist = useCallback(
    (id: string) => {
      const next = value.artistIds.includes(id)
        ? value.artistIds.filter((a) => a !== id)
        : [...value.artistIds, id]
      onChange({ ...value, artistIds: next })
    },
    [value, onChange],
  )

  const toggleStatus = useCallback(
    (status: BookingStatus) => {
      const next = value.statuses.includes(status)
        ? value.statuses.filter((s) => s !== status)
        : [...value.statuses, status]
      onChange({ ...value, statuses: next })
    },
    [value, onChange],
  )

  const toggleDeposit = useCallback(() => {
    onChange({ ...value, hasDeposit: !value.hasDeposit })
  }, [value, onChange])

  // Keyboard: Escape closes popovers
  const containerRef = useRef<HTMLDivElement>(null)
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setArtistPopoverOpen(false)
        setStatusPopoverOpen(false)
      }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [])

  const artistChipLabel = (() => {
    if (value.artistIds.length === 0) return 'Artist'
    const first = artists.find((a) => a.id === value.artistIds[0])
    const name = first?.display_name ?? 'Artist'
    return value.artistIds.length > 1
      ? `${name.split(' ')[0]} +${value.artistIds.length - 1}`
      : (name.split(' ')[0] ?? name)
  })()

  const statusChipLabel =
    value.statuses.length === 0
      ? 'Status'
      : value.statuses.length === 1
        ? (value.statuses[0] === 'in_progress' ? 'In Progress' : value.statuses[0].charAt(0).toUpperCase() + value.statuses[0].slice(1))
        : `Status · ${value.statuses.length}`

  return (
    <div
      ref={containerRef}
      className="flex items-center gap-2 px-6 py-2.5 border-b border-border/40 overflow-x-auto scrollbar-none"
      role="toolbar"
      aria-label="Appointment filters"
    >
      {/* Today */}
      <Chip
        active={value.dateShortcut === 'today'}
        aria-pressed={value.dateShortcut === 'today'}
        onClick={() => setDateShortcut('today')}
      >
        Today
      </Chip>

      {/* This week */}
      <Chip
        active={value.dateShortcut === 'this_week'}
        aria-pressed={value.dateShortcut === 'this_week'}
        onClick={() => setDateShortcut('this_week')}
      >
        This week
      </Chip>

      {/* Artist popover */}
      <Popover open={artistPopoverOpen} onOpenChange={setArtistPopoverOpen}>
        <PopoverTrigger asChild>
          <div>
            <Chip
              active={value.artistIds.length > 0}
              hasPopover
              aria-expanded={artistPopoverOpen}
              aria-haspopup="listbox"
            >
              {artistChipLabel}
            </Chip>
          </div>
        </PopoverTrigger>
        <PopoverContent className="w-56 p-2" align="start">
          <p className="text-xs font-medium text-muted-foreground px-2 pb-2">Artists</p>
          <div className="space-y-0.5">
            {artists.map((artist) => (
              <label
                key={artist.id}
                className="flex items-center gap-2 rounded-md px-2 py-1.5 cursor-pointer hover:bg-muted/50 text-sm"
              >
                <Checkbox
                  checked={value.artistIds.includes(artist.id)}
                  onCheckedChange={() => toggleArtist(artist.id)}
                  aria-label={artist.display_name}
                />
                <span className="h-6 w-6 rounded-full bg-primary/10 text-primary flex items-center justify-center text-xs font-semibold shrink-0">
                  {artist.display_name[0]}
                </span>
                <span className="truncate">{artist.display_name}</span>
              </label>
            ))}
            {artists.length === 0 && (
              <p className="text-xs text-muted-foreground px-2 py-1">No artists</p>
            )}
          </div>
          {value.artistIds.length > 0 && (
            <button
              type="button"
              className="mt-2 w-full text-xs text-muted-foreground hover:text-foreground text-left px-2 py-1"
              onClick={() => onChange({ ...value, artistIds: [] })}
            >
              Clear
            </button>
          )}
        </PopoverContent>
      </Popover>

      {/* Status popover */}
      <Popover open={statusPopoverOpen} onOpenChange={setStatusPopoverOpen}>
        <PopoverTrigger asChild>
          <div>
            <Chip
              active={value.statuses.length > 0}
              hasPopover
              aria-expanded={statusPopoverOpen}
              aria-haspopup="listbox"
            >
              {statusChipLabel}
            </Chip>
          </div>
        </PopoverTrigger>
        <PopoverContent className="w-56 p-2" align="start">
          <p className="text-xs font-medium text-muted-foreground px-2 pb-2">Status</p>
          <div className="space-y-0.5">
            {ALL_STATUSES.map((status) => (
              <label
                key={status}
                className="flex items-center gap-2 rounded-md px-2 py-1.5 cursor-pointer hover:bg-muted/50"
              >
                <Checkbox
                  checked={value.statuses.includes(status)}
                  onCheckedChange={() => toggleStatus(status)}
                  aria-label={status}
                />
                <AppointmentStatusBadge status={status} />
              </label>
            ))}
          </div>
          {value.statuses.length > 0 && (
            <button
              type="button"
              className="mt-2 w-full text-xs text-muted-foreground hover:text-foreground text-left px-2 py-1"
              onClick={() => onChange({ ...value, statuses: [] })}
            >
              Clear
            </button>
          )}
        </PopoverContent>
      </Popover>

      {/* Has deposit toggle */}
      <Chip
        active={value.hasDeposit}
        aria-pressed={value.hasDeposit}
        onClick={toggleDeposit}
      >
        Has deposit
      </Chip>

      {/* Clear all — shown when any filter active */}
      {(value.dateShortcut !== '' || value.artistIds.length > 0 || value.statuses.length > 0 || value.hasDeposit) && (
        <button
          type="button"
          className="inline-flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground ml-1 shrink-0"
          onClick={() =>
            onChange({ dateShortcut: '', artistIds: [], statuses: [], hasDeposit: false })
          }
          aria-label="Clear all filters"
        >
          <X className="h-3 w-3" />
          Clear
        </button>
      )}
    </div>
  )
}

// URL-sync hook for filter bar state
export function useAppointmentFilterBarSync(): [FilterBarState, (next: FilterBarState) => void] {
  const router = useRouter()
  const searchParams = useSearchParams()
  const pathname = usePathname()

  const value: FilterBarState = {
    dateShortcut: (searchParams.get('date_filter') as FilterBarState['dateShortcut']) ?? '',
    artistIds: searchParams.get('artist_ids')?.split(',').filter(Boolean) ?? [],
    statuses: (searchParams.get('statuses')?.split(',').filter(Boolean) ?? []) as BookingStatus[],
    hasDeposit: searchParams.get('has_deposit') === '1',
  }

  const onChange = useCallback(
    (next: FilterBarState) => {
      const params = new URLSearchParams(searchParams.toString())

      if (next.dateShortcut) {
        params.set('date_filter', next.dateShortcut)
      } else {
        params.delete('date_filter')
      }

      if (next.artistIds.length > 0) {
        params.set('artist_ids', next.artistIds.join(','))
      } else {
        params.delete('artist_ids')
      }

      if (next.statuses.length > 0) {
        params.set('statuses', next.statuses.join(','))
      } else {
        params.delete('statuses')
      }

      if (next.hasDeposit) {
        params.set('has_deposit', '1')
      } else {
        params.delete('has_deposit')
      }

      params.set('page', '1')

      router.replace(`${pathname}?${params.toString()}`, { scroll: false })
    },
    [router, searchParams, pathname],
  )

  return [value, onChange]
}

