const { data, isLoading, error } = useQuery<BookingsResponse>({
  queryKey: ['bookings', 'table', debouncedSearch, filterState, dateFilter, page],
  queryFn: async () => {
    const params = new URLSearchParams({ per_page: String(PER_PAGE), page: String(page) })
    if (debouncedSearch) params.set('q', debouncedSearch)
    // Status from filterState (multi) or legacy single
    if (filterState.statuses.length > 0) {
      filterState.statuses.forEach((s) => params.append('status', s))
    }
    if (filterState.artistIds.length > 0) {
      filterState.artistIds.forEach((id) => params.append('artist_id', id))
    }
    if (filterState.hasDeposit) params.set('deposit_status', 'pending')
    const activeDateFilter = dateFilter
    if (activeDateFilter === 'today') {
      const today = new Date()
      const start = new Date(today); start.setHours(0, 0, 0, 0)
      const end = new Date(today); end.setHours(23, 59, 59, 999)
      params.set('from', start.toISOString())
      params.set('to', end.toISOString())
    } else if (activeDateFilter === 'this_week') {
      const now = new Date()
      const mon = new Date(now); mon.setDate(now.getDate() - now.getDay() + 1); mon.setHours(0, 0, 0, 0)
      const sun = new Date(mon); sun.setDate(mon.getDate() + 6); sun.setHours(23, 59, 59, 999)
      params.set('from', mon.toISOString())
      params.set('to', sun.toISOString())
    }
    const res = await fetch(`/api/bookings?${params.toString()}`)
    if (!res.ok) throw new Error('Failed to fetch appointments')
    return res.json() as Promise<BookingsResponse>
  },
})

