'use client'

import { useQuery } from '@tanstack/react-query'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from '@/components/ui/sheet'
import { Skeleton } from '@/components/ui/skeleton'
import { Button } from '@/components/ui/button'
import { AppointmentStatusBadge } from './AppointmentStatusBadge'
import { AppointmentTimeline } from './AppointmentTimeline'
import { DepositStatusBadge } from './DepositStatusBadge'
import { formatCurrency } from '@/lib/utils'
import {
  Calendar,
  Clock,
  User,
  Palette,
  ExternalLink,
  Copy,
} from 'lucide-react'
import { toast } from 'sonner'
import { useRouter } from 'next/navigation'
import type { Database } from '@/lib/supabase/types'

type BookingStatus = Database['public']['Tables']['bookings']['Row']['status']

interface StatusHistoryEntry {
  from: BookingStatus
  to: BookingStatus
  at: string
  by: string
}

interface AppointmentDetailDrawerData {
  id: string
  booking_token: string
  scheduled_at: string
  end_at: string
  duration_min: number
  status: BookingStatus
  price_cents: number
  deposit_cents: number
  deposit_paid: boolean
  status_history: StatusHistoryEntry[] | null
  notes: string | null
  created_at: string
  client: {
    id: string
    first_name: string
    last_name: string | null
    email: string | null
    total_sessions: number
    total_spent_cents: number
  } | null
  artist: {
    id: string
    display_name: string
    avatar_url: string | null
  } | null
  service: {
    id: string
    name: string
    color: string | null
    duration_min: number
  } | null
}

interface AppointmentDetailDrawerProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  /** Booking ID to fetch. When undefined, drawer shows nothing. */
  appointmentId: string | undefined
}

function DrawerSkeleton() {
  return (
    <div className="p-6 space-y-4">
      <div className="flex items-center gap-3">
        <Skeleton className="h-9 w-9 rounded-full" />
        <Skeleton className="h-5 w-40" />
      </div>
      <Skeleton className="h-32 w-full rounded-xl" />
      <Skeleton className="h-24 w-full rounded-xl" />
      <Skeleton className="h-20 w-full rounded-xl" />
    </div>
  )
}

export function AppointmentDetailDrawer({
  open,
  onOpenChange,
  appointmentId,
}: AppointmentDetailDrawerProps) {
  const router = useRouter()

  const { data, isLoading } = useQuery<{ data: AppointmentDetailDrawerData }>({
    queryKey: ['booking', appointmentId],
    queryFn: async () => {
      const res = await fetch(`/api/bookings/${appointmentId}`)
      if (!res.ok) throw new Error('Booking not found')
      return res.json() as Promise<{ data: AppointmentDetailDrawerData }>
    },
    enabled: open && !!appointmentId,
    staleTime: 30_000,
  })

  const booking = data?.data

  const copyToken = () => {
    if (!booking) return
    void navigator.clipboard.writeText(booking.booking_token.split('-')[0]?.toUpperCase() ?? booking.booking_token)
    toast.success('Reference copied')
  }

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="right"
        className="w-full sm:max-w-[480px] flex flex-col overflow-hidden p-0"
      >
        <SheetHeader className="px-6 pt-6 pb-4 border-b border-border/40">
          {isLoading || !booking ? (
            <>
              <Skeleton className="h-5 w-40" />
              <Skeleton className="h-4 w-24 mt-1" />
            </>
          ) : (
            <>
              <div className="flex items-center justify-between gap-2">
                <SheetTitle className="text-base font-semibold">
                  {booking.client
                    ? `${booking.client.first_name} ${booking.client.last_name ?? ''}`.trim()
                    : 'Appointment'}
                </SheetTitle>
                <AppointmentStatusBadge status={booking.status} />
              </div>
              <SheetDescription asChild>
                <div className="flex items-center gap-2 mt-1">
                  <span className="text-xs text-muted-foreground font-mono">
                    #{(booking.booking_token.split('-')[0] ?? booking.booking_token).toUpperCase()}
                  </span>
                  <button
                    type="button"
                    onClick={copyToken}
                    className="h-4 w-4 text-muted-foreground hover:text-foreground"
                    aria-label="Copy booking reference"
                  >
                    <Copy className="h-3.5 w-3.5" />
                  </button>
                </div>
              </SheetDescription>
            </>
          )}
        </SheetHeader>

        <div className="flex-1 overflow-y-auto px-6 py-4 space-y-4">
          {isLoading ? (
            <DrawerSkeleton />
          ) : !booking ? (
            <p className="text-sm text-muted-foreground text-center py-8">
              Select an appointment to view details
            </p>
          ) : (
            <>
              {/* At-a-glance card */}
              <div className="rounded-xl border border-border/60 p-4 space-y-3">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
                  Appointment
                </p>

                <div className="space-y-2 text-sm">
                  <div className="flex items-start gap-2">
                    <Calendar className="h-3.5 w-3.5 text-muted-foreground mt-0.5 shrink-0" />
                    <span>
                      {new Date(booking.scheduled_at).toLocaleDateString('en-US', {
                        weekday: 'long',
                        month: 'long',
                        day: 'numeric',
                        year: 'numeric',
                      })}
                    </span>
                  </div>
                  <div className="flex items-start gap-2">
                    <Clock className="h-3.5 w-3.5 text-muted-foreground mt-0.5 shrink-0" />
                    <span className="tabular-nums">
                      {new Date(booking.scheduled_at).toLocaleTimeString('en-US', {
                        hour: '2-digit',
                        minute: '2-digit',
                      })}
                      {' – '}
                      {new Date(booking.end_at).toLocaleTimeString('en-US', {
                        hour: '2-digit',
                        minute: '2-digit',
                      })}
                      <span className="text-muted-foreground ml-1">· {booking.duration_min} min</span>
                    </span>
                  </div>
                  {booking.service && (
                    <div className="flex items-start gap-2">
                      <Palette className="h-3.5 w-3.5 text-muted-foreground mt-0.5 shrink-0" />
                      <div className="flex items-center gap-1.5">
                        {booking.service.color && (
