                      <span className="text-xs font-semibold text-primary">
                        {booking.client.first_name[0]}
                        {booking.client.last_name?.[0] ?? ''}
                      </span>
                    </div>
                    <div className="min-w-0">
                      <p className="text-sm font-medium truncate">
                        {booking.client.first_name} {booking.client.last_name ?? ''}
                      </p>
                      {booking.client.email && (
                        <p className="text-xs text-muted-foreground truncate">
                          {booking.client.email}
                        </p>
                      )}
                    </div>
                  </div>
                  <div className="flex gap-4 pt-1 border-t border-border/40">
                    <div>
                      <p className="text-xs text-muted-foreground">Sessions</p>
                      <p className="text-sm font-medium tabular-nums">
                        {booking.client.total_sessions}
                      </p>
                    </div>
                    <div>
                      <p className="text-xs text-muted-foreground">LTV</p>
                      <p className="text-sm font-medium tabular-nums">
                        {formatCurrency(booking.client.total_spent_cents)}
                      </p>
                    </div>
                  </div>
                </div>
              )}

              {/* Status timeline */}
              <div className="rounded-xl border border-border/60 p-4 space-y-3">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
                  Status history
                </p>
                <AppointmentTimeline
                  status={booking.status}
                  createdAt={booking.created_at}
                  scheduledAt={booking.scheduled_at}
                  statusHistory={booking.status_history ?? []}
                />
              </div>

              {/* Notes */}
              {booking.notes && (
                <div className="rounded-xl border border-border/60 p-4">
                  <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide mb-2">
                    Notes
                  </p>
                  <p className="text-sm text-foreground/80 whitespace-pre-wrap">{booking.notes}</p>
                </div>
              )}
            </>
          )}
        </div>

        {/* Footer */}
        {booking && (
          <div className="border-t border-border/40 px-6 py-4 flex items-center justify-between gap-3">
            <Button
              variant="ghost"
              size="sm"
              className="text-xs gap-1.5"
              onClick={() => {
                onOpenChange(false)
                router.push(`/appointments/${booking.id}`)
              }}
            >
              <ExternalLink className="h-3.5 w-3.5" />
              Open full page
            </Button>
          </div>
        )}
      </SheetContent>
    </Sheet>
  )
}

