{/* Step labels */}
<div className="flex flex-col justify-between py-0.5">
  {TIMELINE_STEPS.map((step) => {
    const stepOrder = STATUS_ORDER[step.status]
    const isDone = !isTerminal && currentOrder > stepOrder
    const isActive = !isTerminal && currentOrder === stepOrder

    // Find history entry for this step transition
    const historyEntry = statusHistory.find((h) => h.to === step.status)

    const timestamp: string | null = (() => {
      if (historyEntry) {
        return new Date(historyEntry.at).toLocaleDateString('en-US', {
          month: 'short',
