'use client'

import { useState, useCallback } from 'react'
import { useMutation, useQueryClient } from '@tanstack/react-query'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from '@/components/ui/sheet'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import { Label } from '@/components/ui/label'
import { Checkbox } from '@/components/ui/checkbox'
import { Calendar } from '@/components/ui/calendar'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { Input } from '@/components/ui/input'
import { Loader2, CalendarDays } from 'lucide-react'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'
import { logger } from '@/lib/logger'

interface AffectedAppointment {
  id: string
  clientName: string
  scheduledAt: string
}

interface BulkRescheduleSheetProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  appointments: AffectedAppointment[]
  onSuccess: () => void
}

export function BulkRescheduleSheet({
  open,
  onOpenChange,
  appointments,
  onSuccess,
}: BulkRescheduleSheetProps) {
  const queryClient = useQueryClient()
  const [newDate, setNewDate] = useState<Date | undefined>(undefined)
  const [newTime, setNewTime] = useState('')
  const [notifyClients, setNotifyClients] = useState(true)
  const [reason, setReason] = useState('')
  const [calPopoverOpen, setCalPopoverOpen] = useState(false)
  const [dateError, setDateError] = useState<string | null>(null)

  const reset = useCallback(() => {
    setNewDate(undefined)
    setNewTime('')
    setNotifyClients(true)
    setReason('')
    setDateError(null)
  }, [])

  const canSubmit = !!newDate && !!newTime

  const mutation = useMutation({
    mutationFn: async () => {
      if (!newDate || !newTime) throw new Error('Date and time required')
      const [hoursStr, minutesStr] = newTime.split(':')
      const hours = parseInt(hoursStr ?? '0', 10)
      const minutes = parseInt(minutesStr ?? '0', 10)
      const dateTime = new Date(newDate)
      dateTime.setHours(hours, minutes, 0, 0)

      if (dateTime <= new Date()) {
        setDateError('New date must be in the future')
        throw new Error('New date must be in the future')
      }
      setDateError(null)

      await Promise.all(
        appointments.map((appt) =>
          fetch(`/api/bookings/${appt.id}/reschedule`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              scheduled_at: dateTime.toISOString(),
              notify_client: notifyClients,
              ...(reason ? { reason } : {}),
            }),
          }).then(async (res) => {
            if (!res.ok) {
              const err = await res.json() as { error?: string }
              throw new Error(err.error ?? `Failed to reschedule ${appt.id}`)
            }
          })
        )
      )
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['bookings'] })
      toast.success(`${appointments.length} appointment${appointments.length !== 1 ? 's' : ''} rescheduled`)
      reset()
      onSuccess()
      onOpenChange(false)
    },
    onError: (err: Error) => {
      if (!err.message.includes('future')) {
        toast.error(err.message)
        logger.error({ err }, 'bulk reschedule failed')
      }
    },
  })

  const n = appointments.length

  return (
    <Sheet open={open} onOpenChange={(v) => { if (!v) reset(); onOpenChange(v) }}>
      <SheetContent side="right" className="sm:max-w-md flex flex-col overflow-hidden p-0">
        <SheetHeader className="px-6 pt-6 pb-4 border-b border-border/40">
          <SheetTitle>Reschedule {n} appointment{n !== 1 ? 's' : ''}</SheetTitle>
          <SheetDescription className="sr-only">
            Choose a new date and time for the selected appointments
          </SheetDescription>
        </SheetHeader>

        <div className="flex-1 overflow-y-auto px-6 py-4 space-y-5">
          {/* Affected list */}
          <div>
            <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide mb-2">
              Affected appointments
            </p>
            <div className="max-h-48 overflow-y-auto space-y-1.5 rounded-lg border border-border/60 p-2">
              {appointments.map((appt) => (
                <div key={appt.id} className="flex items-center gap-2 py-1 px-2">
                  <div className="h-6 w-6 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
                    <span className="text-xs font-semibold text-primary">
                      {appt.clientName[0]}
                    </span>
                  </div>
                  <span className="text-sm truncate flex-1">{appt.clientName}</span>
                  <span className="text-xs text-muted-foreground tabular-nums shrink-0">
                    {new Date(appt.scheduledAt).toLocaleDateString('en-US', {
                      month: 'short', day: 'numeric',
                    })}
                  </span>
                </div>
              ))}
            </div>
          </div>

          {/* Date picker */}
          <div className="space-y-1.5">
            <Label className="text-xs">New date</Label>
            <Popover open={calPopoverOpen} onOpenChange={setCalPopoverOpen}>
              <PopoverTrigger
                render={
                  <button
                    type="button"
                    className={cn(
                      'w-full flex items-center gap-2 rounded-md border border-input bg-background px-3 py-2 text-sm text-left',
                      !newDate && 'text-muted-foreground'
                    )}
                  >
                    <CalendarDays className="h-4 w-4 shrink-0" />
                    {newDate
                      ? newDate.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' })
                      : 'Pick a date'}
                  </button>
                }
              />
              <PopoverContent className="w-auto p-0" align="start">
                <Calendar
                  mode="single"
                  selected={newDate}
                  onSelect={(d) => { setNewDate(d); setCalPopoverOpen(false) }}
                  disabled={(date) => date < new Date(new Date().setHours(0, 0, 0, 0))}
                />
              </PopoverContent>
            </Popover>
          </div>

          {/* Time input */}
          <div className="space-y-1.5">
            <Label htmlFor="bulk-reschedule-time" className="text-xs">New time</Label>
            <Input
              id="bulk-reschedule-time"
              type="time"
              value={newTime}
              onChange={(e) => setNewTime(e.target.value)}
              className="text-sm"
            />
            {dateError && (
              <p className="text-xs text-destructive">{dateError}</p>
            )}
          </div>

          {/* Notify checkbox */}
          <label className="flex items-start gap-2 cursor-pointer">
            <Checkbox
              checked={notifyClients}
              onCheckedChange={(v) => setNotifyClients(!!v)}
              className="mt-0.5"
            />
            <span className="text-sm">
              Send reschedule notification to {n} client{n !== 1 ? 's' : ''}
            </span>
          </label>

          {/* Reason */}
          <div className="space-y-1.5">
            <Label htmlFor="bulk-reschedule-reason" className="text-xs">
              Reason (optional)
            </Label>
            <Textarea
              id="bulk-reschedule-reason"
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder="Reason for reschedule (sent to clients if notified)"
              className="text-sm min-h-[80px] resize-none"
              maxLength={500}
            />
          </div>
        </div>

        <div className="border-t border-border/40 px-6 py-4 flex items-center justify-between gap-3">
          <Button variant="outline" onClick={() => { reset(); onOpenChange(false) }}>
            Cancel
          </Button>
          <Button
            disabled={!canSubmit || mutation.isPending}
            onClick={() => mutation.mutate()}
          >
            {mutation.isPending ? (
              <>
                <Loader2 className="h-3.5 w-3.5 animate-spin mr-1.5" />
                Rescheduling...
              </>
            ) : (
              `Reschedule ${n} appointment${n !== 1 ? 's' : ''} →`
            )}
          </Button>
        </div>
      </SheetContent>
    </Sheet>
  )
}

'use client'

import { useState, useCallback } from 'react'
import { useMutation, useQueryClient } from '@tanstack/react-query'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from '@/components/ui/sheet'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import { Label } from '@/components/ui/label'
import { Checkbox } from '@/components/ui/checkbox'
import { AlertCircle, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { logger } from '@/lib/logger'

interface AffectedAppointment {
  id: string
  clientName: string
  scheduledAt: string
  depositPaid: boolean
}

interface BulkCancelSheetProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  appointments: AffectedAppointment[]
  onSuccess: () => void
}

const CANCEL_REASONS = [
  'Client request',
  'Studio schedule conflict',
  'Artist unavailable',
  'No-show (missed)',
  'Weather / emergency',
  'Other',
] as const

type CancelReason = (typeof CANCEL_REASONS)[number]

export function BulkCancelSheet({
  open,
  onOpenChange,
  appointments,
  onSuccess,
}: BulkCancelSheetProps) {
  const queryClient = useQueryClient()
  const [reason, setReason] = useState<CancelReason | ''>('')
  const [otherReason, setOtherReason] = useState('')
  const [notifyClients, setNotifyClients] = useState(true)
  const [refundDeposits, setRefundDeposits] = useState(false)

  const hasAnyDeposit = appointments.some((a) => a.depositPaid)
  const n = appointments.length

  const canSubmit = reason !== ''

  const reset = useCallback(() => {
    setReason('')
    setOtherReason('')
    setNotifyClients(true)
    setRefundDeposits(false)
  }, [])

  const mutation = useMutation({
    mutationFn: async () => {
      const finalReason = reason === 'Other' ? otherReason : reason
      await Promise.all(
        appointments.map((appt) =>
          fetch(`/api/bookings/${appt.id}/status`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              status: 'cancelled',
              reason: finalReason,
              notify_client: notifyClients,
              ...(refundDeposits && appt.depositPaid ? { initiate_refund: true } : {}),
            }),
          }).then(async (res) => {
            if (!res.ok) {
              const err = await res.json() as { error?: string }
              throw new Error(err.error ?? `Failed to cancel ${appt.id}`)
            }
          })
        )
      )
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['bookings'] })
      toast.success(`${n} appointment${n !== 1 ? 's' : ''} cancelled`)
      reset()
      onSuccess()
      onOpenChange(false)
    },
    onError: (err: Error) => {
      toast.error(err.message)
      logger.error({ err }, 'bulk cancel failed')
    },
  })

  return (
    <Sheet open={open} onOpenChange={(v) => { if (!v) reset(); onOpenChange(v) }}>
      <SheetContent side="right" className="sm:max-w-md flex flex-col overflow-hidden p-0">
        <SheetHeader className="px-6 pt-6 pb-4 border-b border-border/40">
          <SheetTitle>Cancel {n} appointment{n !== 1 ? 's' : ''}</SheetTitle>
          <SheetDescription className="sr-only">
            Cancel the selected appointments with a reason
          </SheetDescription>
        </SheetHeader>

        <div className="flex-1 overflow-y-auto px-6 py-4 space-y-5">
          {/* Destructive alert */}
          <div className="flex items-start gap-2 rounded-lg bg-destructive/10 border border-destructive/20 px-3 py-2.5">
            <AlertCircle className="h-4 w-4 text-destructive mt-0.5 shrink-0" />
            <p className="text-sm text-destructive">
              This will cancel {n} appointment{n !== 1 ? 's' : ''} and cannot be undone.
            </p>
          </div>

          {/* Affected list */}
          <div>
            <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide mb-2">
              Affected appointments
            </p>
            <div className="max-h-48 overflow-y-auto space-y-1.5 rounded-lg border border-border/60 p-2">
              {appointments.map((appt) => (
                <div key={appt.id} className="flex items-center gap-2 py-1 px-2">
                  <div className="h-6 w-6 rounded-full bg-destructive/10 flex items-center justify-center shrink-0">
                    <span className="text-xs font-semibold text-destructive">
                      {appt.clientName[0]}
                    </span>
                  </div>
                  <span className="text-sm truncate flex-1">{appt.clientName}</span>
                  <span className="text-xs text-muted-foreground tabular-nums shrink-0">
                    {new Date(appt.scheduledAt).toLocaleDateString('en-US', {
                      month: 'short', day: 'numeric',
                    })}
                  </span>
                </div>
              ))}
            </div>
          </div>

          {/* Reason select */}
          <div className="space-y-1.5">
            <Label htmlFor="bulk-cancel-reason" className="text-xs">
              Cancellation reason *
            </Label>
            <select
              id="bulk-cancel-reason"
              value={reason}
              onChange={(e) => setReason(e.target.value as CancelReason | '')}
              className="w-full h-9 rounded-md border border-input bg-background px-3 text-sm text-foreground"
            >
              <option value="">Select a reason</option>
              {CANCEL_REASONS.map((r) => (
                <option key={r} value={r}>{r}</option>
              ))}
            </select>
          </div>

          {reason === 'Other' && (
            <div className="space-y-1.5">
              <Label htmlFor="bulk-cancel-other" className="text-xs">Other reason</Label>
              <Textarea
                id="bulk-cancel-other"
                value={otherReason}
                onChange={(e) => setOtherReason(e.target.value)}
                placeholder="Describe the reason..."
                className="text-sm min-h-[80px] resize-none"
                maxLength={500}
              />
            </div>
          )}

          {/* Notify checkbox */}
          <label className="flex items-start gap-2 cursor-pointer">
            <Checkbox
              checked={notifyClients}
              onCheckedChange={(v) => setNotifyClients(!!v)}
              className="mt-0.5"
            />
            <span className="text-sm">
              Send cancellation notice to {n} client{n !== 1 ? 's' : ''}
            </span>
          </label>

          {/* Refund deposits — only when any appointment has deposit paid */}
          {hasAnyDeposit && (
            <div className="space-y-1">
              <label className="flex items-start gap-2 cursor-pointer">
                <Checkbox
                  checked={refundDeposits}
                  onCheckedChange={(v) => setRefundDeposits(!!v)}
                  className="mt-0.5"
                />
                <span className="text-sm">
                  Initiate deposit refunds where applicable
                </span>
              </label>
              <p className="text-xs text-muted-foreground ml-6">
                Refunds processed via Dodo Payments
              </p>
            </div>
          )}
        </div>

        <div className="border-t border-border/40 px-6 py-4 flex items-center justify-between gap-3">
          <Button variant="outline" onClick={() => { reset(); onOpenChange(false) }}>
            Keep appointments
          </Button>
          <Button
            variant="destructive"
            disabled={!canSubmit || mutation.isPending}
            onClick={() => mutation.mutate()}
          >
            {mutation.isPending ? (
              <>
                <Loader2 className="h-3.5 w-3.5 animate-spin mr-1.5" />
                Cancelling...
              </>
            ) : (
              `Cancel ${n} appointment${n !== 1 ? 's' : ''}`
            )}
          </Button>
        </div>
      </SheetContent>
    </Sheet>
  )
}

import { ShieldCheck, RefreshCw, CreditCard } from 'lucide-react'
import { formatCurrency } from '@/lib/utils'

interface AppointmentPoliciesCardProps {
  cancellationHours: number
  rescheduleFeesCents: number
  depositCents: number
  depositPct: number
}

export function AppointmentPoliciesCard({
  cancellationHours,
  rescheduleFeesCents,
  depositCents,
  depositPct,
}: AppointmentPoliciesCardProps) {
  // Render nothing if no meaningful policy data
  if (cancellationHours === 0 && rescheduleFeesCents === 0 && depositCents === 0) return null

  return (
    <div className="rounded-xl border border-border/60 p-5 space-y-3">
      <p className="text-sm font-semibold">Policies</p>
      <div className="space-y-2">
        {cancellationHours > 0 && (
          <div className="flex items-start gap-2 text-sm">
            <ShieldCheck className="h-3.5 w-3.5 text-muted-foreground mt-0.5 shrink-0" />
            <span>Cancellation: {cancellationHours}h notice required</span>
          </div>
        )}
        <div className="flex items-start gap-2 text-sm">
          <RefreshCw className="h-3.5 w-3.5 text-muted-foreground mt-0.5 shrink-0" />
          <span>
            {rescheduleFeesCents > 0
              ? `Reschedule fee: ${formatCurrency(rescheduleFeesCents)}`
              : 'No reschedule fee'}
          </span>
        </div>
        {depositCents > 0 && (
          <div className="flex items-start gap-2 text-sm">
            <CreditCard className="h-3.5 w-3.5 text-muted-foreground mt-0.5 shrink-0" />
            <span>
              Deposit: {depositPct}% ({formatCurrency(depositCents)})
            </span>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { FileText, ExternalLink } from 'lucide-react'
import { Skeleton } from '@/components/ui/skeleton'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

interface ConsentFormLink {
  id: string
  submissionId: string | null
  templateName: string
  status: 'signed' | 'pending' | 'expired'
  signedAt: string | null
}

interface AppointmentConsentLinksProps {
  forms: ConsentFormLink[]
  isLoading?: boolean
  onRequestConsent?: () => void
}

const STATUS_BADGE: Record<ConsentFormLink['status'], string> = {
  signed: 'badge-completed',
  pending: 'badge-pending',
  expired: 'badge-cancelled',
}

const STATUS_LABELS: Record<ConsentFormLink['status'], string> = {
  signed: 'Signed',
  pending: 'Pending',
  expired: 'Expired',
}

export function AppointmentConsentLinks({
  forms,
