      {isLoading ? (
        <div className="space-y-2">
          <Skeleton className="h-6 w-full" />
          <Skeleton className="h-6 w-3/4" />
        </div>
      ) : forms.length === 0 ? (
        <div className="space-y-2">
          <p className="text-xs text-muted-foreground">No consent forms for this appointment</p>
          {onRequestConsent && (
            <Button
              variant="ghost"
              size="sm"
              className="h-7 text-xs"
              onClick={onRequestConsent}
            >
              Request consent →
            </Button>
          )}
