                )}
              </div>
              <span className={cn('inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium shrink-0', STATUS_BADGE[form.status])}>
                {STATUS_LABELS[form.status]}
              </span>
              {form.submissionId && (
                <a
                  href={`/consent-forms/submissions/${form.submissionId}`}
                  target="_blank"
                  rel="noreferrer"
                  className="h-6 w-6 flex items-center justify-center text-muted-foreground hover:text-foreground shrink-0"
                  aria-label={`Open ${form.templateName} consent form`}
                >
                  <ExternalLink className="h-3 w-3" />
                </a>
              )}
            </div>
          ))}
        </div>
      )}
