interface Service {
  id: string
  name: string
  description: string | null
  duration_min: number
  base_price_cents: number
  deposit_cents: number
  deposit_required: boolean
  color: string | null
}

interface Artist {
  id: string
  display_name: string
  avatar_url: string | null
  specialties: string[]
}

interface DraftState {
  serviceId: string | null
  artistId: string | null
  slot: string | null
  clientId: string | null
  notes: string
}

const STEPS = ['Client', 'Service', 'Time'] as const

const DRAFT_KEY_PREFIX = 'inkos_appt_draft'

function getDraftKey(studioId: string | null, userId: string | null) {
  return `${DRAFT_KEY_PREFIX}_${studioId ?? 'unknown'}_${userId ?? 'anonymous'}`
}

function StepIndicator({
  steps,
  currentStep,
}: {
  steps: readonly string[]
  currentStep: number
}) {
  return (
    <nav
      role="navigation"
      aria-label="Booking steps"
      className="flex items-center gap-0 w-full"
    >
      {steps.map((label, index) => (
        <div key={label} className="flex items-center flex-1 last:flex-none">
          <div className="flex flex-col items-center gap-1">
            <div
              aria-current={index === currentStep ? 'step' : undefined}
              className={cn(
                'h-8 w-8 rounded-full flex items-center justify-center border-2 text-xs font-medium transition-all',
                index < currentStep
                  ? 'bg-primary border-transparent text-primary-foreground'
                  : index === currentStep
                    ? 'border-primary text-primary bg-background'
                    : 'border-border/60 text-muted-foreground bg-background',
              )}
            >
              {index < currentStep ? (
                <Check className="h-4 w-4" />
              ) : (
                index + 1
              )}
            </div>
            <span
              className={cn(
                'text-xs',
                index === currentStep ? 'text-foreground font-medium' : 'text-muted-foreground',
              )}
            >
              {label}
            </span>
          </div>
          {index < steps.length - 1 && (
            <div
              className={cn(
                'flex-1 h-0.5 mx-2 mb-5',
                index < currentStep ? 'bg-primary' : 'bg-border/60',
              )}
            />
          )}
        </div>
      ))}
    </nav>
  )
}

