interface AppointmentWizardClientProps {
  studioId: string | null
  userId: string | null
}

export function AppointmentWizardClient({
  studioId,
  userId,
}: AppointmentWizardClientProps) {
  const router = useRouter()
  const queryClient = useQueryClient()

  const [step, setStep] = useState(0)
  const [prevStep, setPrevStep] = useState(0)
  const [direction, setDirection] = useState<'forward' | 'back'>('forward')

  const [selectedClientId, setSelectedClientId] = useState<string | null>(null)
  const [clientName, setClientName] = useState<string | null>(null)
  const [newClientData, setNewClientData] = useState<{
    first_name: string; last_name: string; email: string; phone: string
  } | null>(null)
  const [selectedServiceId, setSelectedServiceId] = useState<string | null>(null)
  const [selectedArtistId, setSelectedArtistId] = useState<string | null>(null)
  const [selectedSlot, setSelectedSlot] = useState<string | null>(null)
  const [notes, setNotes] = useState('')
  const [draftSaved, setDraftSaved] = useState(false)
  const [draftRestoredBanner, setDraftRestoredBanner] = useState(false)

  const draftKey = getDraftKey(studioId, userId)

  // Restore draft on mount
  useEffect(() => {
    try {
      const raw = localStorage.getItem(draftKey)
      if (!raw) return
      const draft = JSON.parse(raw) as DraftState
      if (draft.serviceId) setSelectedServiceId(draft.serviceId)
      if (draft.artistId) setSelectedArtistId(draft.artistId)
      if (draft.slot) setSelectedSlot(draft.slot)
      if (draft.clientId) setSelectedClientId(draft.clientId)
      if (draft.notes) setNotes(draft.notes)
      setDraftRestoredBanner(true)
    } catch {
      // ignore malformed draft
    }
  }, [draftKey])

  // Autosave draft
  const saveTimeout = useRef<ReturnType<typeof setTimeout> | null>(null)
  useEffect(() => {
    if (saveTimeout.current) clearTimeout(saveTimeout.current)
    saveTimeout.current = setTimeout(() => {
      const draft: DraftState = {
        serviceId: selectedServiceId,
        artistId: selectedArtistId,
        slot: selectedSlot,
        clientId: selectedClientId,
        notes,
      }
      localStorage.setItem(draftKey, JSON.stringify(draft))
      setDraftSaved(true)
    }, 1000)
    return () => {
      if (saveTimeout.current) clearTimeout(saveTimeout.current)
    }
  }, [draftKey, selectedServiceId, selectedArtistId, selectedSlot, selectedClientId, notes])

  const clearDraft = useCallback(() => {
    localStorage.removeItem(draftKey)
    setDraftSaved(false)
    setDraftRestoredBanner(false)
  }, [draftKey])

  // Fetch services
  const { data: servicesData, isLoading: servicesLoading } = useQuery<{ data: Service[] }>({
    queryKey: ['services'],
    queryFn: async () => {
      const res = await fetch('/api/services')
      if (!res.ok) throw new Error('Failed to fetch services')
      return res.json() as Promise<{ data: Service[] }>
    },
    enabled: step === 1,
  })

  // Fetch artists filtered by service
  const { data: artistsData, isLoading: artistsLoading } = useQuery<{ data: Artist[] }>({
    queryKey: ['artists', 'by-service', selectedServiceId],
    queryFn: async () => {
      const url = selectedServiceId
        ? `/api/artists?service_id=${selectedServiceId}&status=active`
        : '/api/artists?status=active'
      const res = await fetch(url)
      if (!res.ok) throw new Error('Failed to fetch artists')
      return res.json() as Promise<{ data: Artist[] }>
    },
    enabled: step === 2,
  })

  const services = servicesData?.data ?? []
  const artists = artistsData?.data ?? []
  const selectedService = services.find((s) => s.id === selectedServiceId) ?? null
  const selectedArtist = artists.find((a) => a.id === selectedArtistId)

  // Step validation
  const canProceed = useCallback((): boolean => {
    if (step === 0) return !!(selectedClientId ?? newClientData)
    if (step === 1) return !!selectedServiceId
    if (step === 2) return !!selectedSlot
    return false
  }, [step, selectedClientId, newClientData, selectedServiceId, selectedSlot])

  const goNext = useCallback(() => {
    if (!canProceed()) return
    setPrevStep(step)
    setDirection('forward')
    setStep((s) => s + 1)
  }, [step, canProceed])

  const goBack = useCallback(() => {
    if (step === 0) {
      router.push('/appointments')
      return
    }
    setPrevStep(step)
    setDirection('back')
    setStep((s) => s - 1)
  }, [step, router])

  const createMutation = useMutation({
    mutationFn: async () => {
      let clientId = selectedClientId
      if (!clientId && newClientData) {
        const res = await fetch('/api/clients', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(newClientData),
        })
        if (!res.ok) {
          const err = await res.json() as { error?: string }
          throw new Error(err.error ?? 'Failed to create client')
        }
        const { data } = await res.json() as { data: { id: string } }
        clientId = data.id
      }

      if (!clientId || !selectedArtistId || !selectedSlot || !selectedServiceId || !selectedService) {
        throw new Error('All fields are required')
      }

      const res = await fetch('/api/bookings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          client_id: clientId,
          artist_id: selectedArtistId,
          service_id: selectedServiceId,
          scheduled_at: selectedSlot,
          duration_min: selectedService.duration_min,
          price_cents: selectedService.base_price_cents,
          deposit_cents: selectedService.deposit_cents,
          ...(notes ? { notes } : {}),
          source: 'internal',
        }),
      })

      if (!res.ok) {
        const err = await res.json() as { error?: string }
        if (err.error?.includes('time slot') || err.error?.includes('23P01')) {
          throw new Error('That time slot is already booked for this artist')
        }
        throw new Error(err.error ?? 'Failed to create booking')
      }

      const { data } = await res.json() as { data: { id: string } }
      return data.id
    },
    onSuccess: (bookingId) => {
      clearDraft()
      void queryClient.invalidateQueries({ queryKey: ['bookings'] })
      toast.success('Appointment created')
      router.push(`/appointments/${bookingId}`)
    },
    onError: (err: Error) => {
      toast.error(err.message)
      logger.error({ err }, 'appointment wizard create failed')
      if (err.message.includes('time slot')) {
        setStep(2)
        setSelectedSlot(null)
      }
    },
  })

  const stepAnimClass =
    direction === 'forward'
      ? 'animate-in fade-in-0 slide-in-from-right-4 duration-200'
      : 'animate-in fade-in-0 slide-in-from-left-4 duration-200'

  const _ = prevStep // used to track prev for direction

  return (
    <div className="max-w-4xl mx-auto px-4 md:px-6 py-8">
      {/* Back link */}
      <Button
        variant="ghost"
        size="sm"
        className="mb-4 -ml-2 gap-1.5 text-muted-foreground hover:text-foreground"
        render={<Link href="/appointments" />}
      >
        <ChevronLeft className="h-4 w-4" />
        Appointments
      </Button>

      <Typography variant="h1" className="mb-6">New Appointment</Typography>

      {/* Draft restored banner */}
      {draftRestoredBanner && (
        <div className="mb-4 flex items-center justify-between rounded-lg bg-muted/40 border border-border/60 px-4 py-2.5 text-sm">
          <span>Draft restored from your last session.</span>
          <button
            type="button"
            className="text-xs text-muted-foreground hover:text-foreground"
            onClick={() => {
              clearDraft()
              setSelectedServiceId(null)
              setSelectedArtistId(null)
              setSelectedSlot(null)
              setSelectedClientId(null)
              setNotes('')
              setDraftRestoredBanner(false)
            }}
          >
            Clear draft ×
          </button>
        </div>
      )}

      <div className="flex flex-col lg:flex-row gap-8">
        {/* Left: step content */}
        <div className="flex-1 min-w-0">
          {/* Step progress bar */}
          <div className="mb-8">
            <StepIndicator steps={STEPS} currentStep={step} />
          </div>

          {/* Step content — keyed to trigger remount + animation */}
          <div key={`step-${step}`} className={cn('motion-safe:', stepAnimClass)}>
            {/* Step 0: Client */}
            {step === 0 && (
              <div className="space-y-4">
                <Typography variant="h2">Who is this appointment for?</Typography>
                <ClientFinder
                  selectedClientId={selectedClientId}
                  onSelectClient={(id, name) => {
                    setSelectedClientId(id)
                    setClientName(name ?? null)
                    setNewClientData(null)
                  }}
                  onNewClient={(data) => {
                    setNewClientData(data)
                    setSelectedClientId(null)
                    setClientName(`${data.first_name} ${data.last_name}`.trim())
                  }}
                />
              </div>
            )}

            {/* Step 1: Service */}
            {step === 1 && (
              <div className="space-y-4" role="radiogroup" aria-label="Select a service">
                <Typography variant="h2">Which service?</Typography>
                {servicesLoading ? (
                  <div className="space-y-2">
                    {Array.from({ length: 4 }).map((_, i) => (
                      <Skeleton key={i} className="h-20 rounded-xl" />
                    ))}
                  </div>
                ) : services.length === 0 ? (
                  <div className="rounded-xl border border-border/60 p-8 text-center space-y-3">
                    <CalendarX className="h-10 w-10 text-muted-foreground/40 mx-auto" />
                    <p className="text-sm font-medium">No services configured</p>
                    <Link
                      href="/settings/services"
                      className="text-xs text-primary hover:underline"
                    >
                      Configure services →
                    </Link>
                  </div>
                ) : (
                  <div className="space-y-2">
                    {services.map((service) => {
                      const isSelected = selectedServiceId === service.id
                      return (
                        <button
                          key={service.id}
                          type="button"
                          role="radio"
                          aria-checked={isSelected}
                          className={cn(
                            'w-full rounded-xl border p-4 text-left transition-all duration-100',
                            isSelected
                              ? 'border-2 border-primary bg-primary/5'
                              : 'border border-border/60 bg-background hover:bg-muted/50',
                          )}
                          onClick={() => setSelectedServiceId(service.id)}
                        >
                          <div className="flex items-start justify-between gap-3">
                            <div className="min-w-0">
                              <div className="flex items-center gap-1.5">
                                {service.color && (
                                  <span
                                    className="h-3 w-3 rounded-full shrink-0"
                                    style={{ backgroundColor: service.color }}
                                  />
                                )}
                                <span className="text-sm font-semibold">{service.name}</span>
                              </div>
                              {service.description && (
                                <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">
                                  {service.description}
                                </p>
                              )}
                              <div className="flex items-center gap-3 mt-2 text-xs text-muted-foreground">
                                <span className="flex items-center gap-1">
                                  <Clock className="h-3 w-3" />
                                  {service.duration_min} min
                                </span>
                                <span className="flex items-center gap-1 tabular-nums">
                                  <CircleDollarSign className="h-3 w-3" />
                                  {formatCurrency(service.base_price_cents)}
                                </span>
                                {service.deposit_required && service.deposit_cents > 0 && (
                                  <span className="flex items-center gap-1 tabular-nums">
                                    <CreditCard className="h-3 w-3" />
                                    Deposit {formatCurrency(service.deposit_cents)}
                                  </span>
                                )}
                              </div>
                            </div>
                            {isSelected && (
                              <Check className="h-4 w-4 text-primary shrink-0 mt-0.5" />
                            )}
                          </div>
                        </button>
                      )
                    })}
                  </div>
                )}
              </div>
            )}

            {/* Step 2: Time */}
            {step === 2 && (
              <div className="space-y-4">
                <div>
                  <Typography variant="h2">Pick a date and time</Typography>
                  {selectedArtist && (
                    <p className="text-sm text-muted-foreground mt-1">
                      With {selectedArtist.display_name}
                    </p>
                  )}
                </div>

                {/* Artist picker if multiple available */}
                {artists.length > 1 && (
                  <div className="space-y-1.5">
                    <Label className="text-xs font-medium">Artist</Label>
                    {artistsLoading ? (
                      <Skeleton className="h-9 w-full" />
                    ) : (
                      <select
                        value={selectedArtistId ?? ''}
                        onChange={(e) => {
                          setSelectedArtistId(e.target.value || null)
                          setSelectedSlot(null)
                        }}
                        className="w-full h-9 rounded-md border border-input bg-background px-3 text-sm text-foreground"
                      >
                        <option value="">Select an artist</option>
                        {artists.map((a) => (
                          <option key={a.id} value={a.id}>{a.display_name}</option>
                        ))}
                      </select>
                    )}
                  </div>
                )}

                {/* Auto-select single artist */}
                {artists.length === 1 && !selectedArtistId && (
                  <p className="text-sm text-muted-foreground">
                    Artist: {artists[0]?.display_name ?? ''}
                  </p>
                )}

                <SlotPicker
                  artistId={selectedArtistId ?? (artists[0]?.id ?? null)}
                  serviceId={selectedServiceId}
                  selectedSlot={selectedSlot}
                  onSelectSlot={(slot) => {
                    setSelectedSlot(slot || null)
                    if (!selectedArtistId && artists[0]) {
                      setSelectedArtistId(artists[0].id)
                    }
                  }}
                />
              </div>
            )}
          </div>

          {/* Footer navigation */}
          <div
            className={cn(
              'flex items-center justify-between gap-3 pt-6 border-t border-border/40 mt-8',
              'lg:relative lg:bottom-auto lg:left-auto lg:right-auto lg:bg-transparent lg:px-0 lg:py-0',
              'fixed bottom-0 left-0 right-0 bg-background border-t border-border/40 px-4 py-3',
              'lg:static',
            )}
            style={{ paddingBottom: 'max(0.75rem, env(safe-area-inset-bottom))' }}
          >
            <Button
              variant="ghost"
              onClick={goBack}
            >
              <ChevronLeft className="h-4 w-4 mr-1" />
              {step === 0 ? 'Cancel' : 'Back'}
            </Button>

            {step < STEPS.length - 1 ? (
              <Button disabled={!canProceed()} onClick={goNext}>
                Next
                <ChevronRight className="h-4 w-4 ml-1" />
              </Button>
            ) : (
              <Button
                disabled={!canProceed() || createMutation.isPending}
                onClick={() => createMutation.mutate()}
              >
                {createMutation.isPending ? (
                  <>
                    <Loader2 className="h-4 w-4 animate-spin mr-1.5" />
                    Booking...
                  </>
                ) : (
                  'Book appointment'
                )}
              </Button>
            )}
          </div>
        </div>

        {/* Right: summary sidebar */}
        <div className="lg:w-72 shrink-0 pb-24 lg:pb-0">
          <SummarySidebar
            service={selectedService}
            artistName={selectedArtist?.display_name ?? null}
            slot={selectedSlot}
            clientName={clientName}
            notes={notes}
            onNotesChange={setNotes}
            draftSaved={draftSaved}
          />
        </div>
      </div>
    </div>
  )
}

