import { useState } from 'react'
import { ChevronDown } from 'lucide-react'
import { cn } from '@/lib/utils'
import { formatCurrency } from '@/lib/utils'

interface PoliciesDisclosureProps {
  cancellationHours?: number
  rescheduleFeesCents?: number
  depositCents?: number
  depositPct?: number
  className?: string
}

export function PoliciesDisclosure({
  cancellationHours = 0,
  rescheduleFeesCents = 0,
  depositCents = 0,
  depositPct = 0,
  className,
}: PoliciesDisclosureProps) {
  const [open, setOpen] = useState(false)

  // If no policy data worth showing, omit entirely
  if (cancellationHours === 0 && rescheduleFeesCents === 0 && depositCents === 0) return null

  return (
    <div className={cn('rounded-xl border border-border/60 overflow-hidden', className)}>
      <button
        type="button"
        className="w-full flex items-center justify-between px-4 py-3 text-sm font-medium hover:bg-muted/40 transition-colors"
        onClick={() => setOpen((v) => !v)}
        aria-expanded={open}
      >
        <span>Booking policies</span>
        <ChevronDown
          className={cn(
            'h-4 w-4 text-muted-foreground transition-transform duration-200',
            open && 'rotate-180',
          )}
        />
      </button>

      {open && (
        <div className="px-4 pb-4 space-y-2 border-t border-border/40 pt-3">
          {cancellationHours > 0 && (
            <div className="flex items-start justify-between gap-2 text-sm">
              <span className="text-muted-foreground">Cancellation notice</span>
              <span className="font-medium text-right">{cancellationHours}h minimum</span>
            </div>
          )}
          {rescheduleFeesCents > 0 && (
            <div className="flex items-start justify-between gap-2 text-sm">
              <span className="text-muted-foreground">Reschedule fee</span>
              <span className="font-medium tabular-nums">{formatCurrency(rescheduleFeesCents)}</span>
            </div>
          )}
          {depositCents > 0 && (
            <div className="flex items-start justify-between gap-2 text-sm">
              <span className="text-muted-foreground">Deposit required</span>
              <span className="font-medium tabular-nums">
                {depositPct > 0 ? `${depositPct}% (${formatCurrency(depositCents)})` : formatCurrency(depositCents)}
              </span>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useQuery } from '@tanstack/react-query'
import { Calendar } from '@/components/ui/calendar'
import { Skeleton } from '@/components/ui/skeleton'
import { cn } from '@/lib/utils'
import { AlertCircle } from 'lucide-react'

interface Slot {
  start: string
  end: string
}

interface AvailabilityData {
  date: string
  artist_id: string
  duration_min: number
  slots: Slot[]
}

interface SlotPickerProps {
  artistId: string | null
  serviceId: string | null
  selectedSlot: string | null
  onSelectSlot: (isoStart: string) => void
}

function getHour(isoString: string): number {
  return new Date(isoString).getHours()
}

function groupSlotsByPeriod(slots: Slot[]): {
  morning: Slot[]
  afternoon: Slot[]
  evening: Slot[]
} {
  const morning: Slot[] = []
  const afternoon: Slot[] = []
  const evening: Slot[] = []

  for (const slot of slots) {
    const h = getHour(slot.start)
    if (h < 12) morning.push(slot)
    else if (h < 17) afternoon.push(slot)
    else evening.push(slot)
  }

  return { morning, afternoon, evening }
}

function SlotGrid({
  slots,
  selectedSlot,
  onSelectSlot,
}: {
  slots: Slot[]
  selectedSlot: string | null
  onSelectSlot: (isoStart: string) => void
}) {
  return (
    <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
      {slots.map((slot) => {
        const time = new Date(slot.start).toLocaleTimeString('en-US', {
          hour: 'numeric',
          minute: '2-digit',
          hour12: true,
        })
        const isSelected = selectedSlot === slot.start
        return (
          <button
            key={slot.start}
            type="button"
            data-selected={isSelected ? 'true' : 'false'}
            data-disabled="false"
            className={cn(
              'time-slot rounded-md border px-2 py-2 text-xs font-medium tabular-nums',
              'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
              isSelected
                ? 'border-[var(--color-booking-step-active)] bg-primary/10 text-primary'
                : 'border-border bg-background text-foreground hover:bg-muted/50',
            )}
            onClick={() => onSelectSlot(slot.start)}
          >
            {time}
          </button>
        )
      })}
    </div>
  )
}

const PERIOD_LABELS: Record<'morning' | 'afternoon' | 'evening', string> = {
  morning: 'Morning',
  afternoon: 'Afternoon',
  evening: 'Evening',
}

export function SlotPicker({
  artistId,
  serviceId,
  selectedSlot,
  onSelectSlot,
}: SlotPickerProps) {
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(new Date())

  // Reset selected slot when date changes
  useEffect(() => {
    onSelectSlot('')
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDate])

  const dateStr = selectedDate
    ? `${selectedDate.getFullYear()}-${String(selectedDate.getMonth() + 1).padStart(2, '0')}-${String(selectedDate.getDate()).padStart(2, '0')}`
    : null

  const { data, isLoading, error } = useQuery<{ data: AvailabilityData }>({
    queryKey: ['availability', artistId, serviceId, dateStr],
    queryFn: async () => {
      const params = new URLSearchParams({
        artist_id: artistId!,
        service_id: serviceId!,
        date: dateStr!,
      })
      const res = await fetch(`/api/public/availability?${params.toString()}`)
      if (!res.ok) throw new Error('Failed to fetch availability')
      return res.json() as Promise<{ data: AvailabilityData }>
    },
    enabled: Boolean(artistId && serviceId && dateStr),
  })

  const slots = data?.data?.slots ?? []
  const grouped = groupSlotsByPeriod(slots)
  const periods = (['morning', 'afternoon', 'evening'] as const).filter(
    (p) => grouped[p].length > 0,
  )

  return (
    <div className="space-y-4">
      <div className="flex justify-center">
        <Calendar
          mode="single"
          selected={selectedDate}
          onSelect={setSelectedDate}
          disabled={(date) => date < new Date(new Date().setHours(0, 0, 0, 0))}
          className="rounded-lg border border-border"
        />
      </div>

      {!artistId || !serviceId ? (
        <p className="text-center text-sm text-muted-foreground py-4">
          Select a service and artist first
        </p>
      ) : isLoading ? (
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
          {Array.from({ length: 8 }).map((_, i) => (
            <Skeleton key={i} className="h-10 rounded-md" />
          ))}
        </div>
      ) : error ? (
        <div className="flex items-center gap-2 text-sm text-destructive py-2">
          <AlertCircle className="h-4 w-4 shrink-0" />
          Failed to load availability
        </div>
      ) : slots.length === 0 ? (
        <p className="text-center text-sm text-muted-foreground py-4">
          No available slots for this date
        </p>
      ) : (
        <div className="space-y-4">
          {periods.map((period) => (
            <div key={period}>
              <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide mb-2">
                {PERIOD_LABELS[period]}
              </p>
              <SlotGrid
                slots={grouped[period]}
                selectedSlot={selectedSlot}
                onSelectSlot={onSelectSlot}
              />
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

