  hint = 'PNG, JPG, WEBP up to 10MB each',
}: FileDropzoneProps) {
  const [files, setFiles] = useState<File[]>([])
  const [dragging, setDragging] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const addFiles = useCallback(
    (newFiles: FileList | null) => {
      if (!newFiles) return
      setError(null)

      const maxBytes = maxSizeMb * 1024 * 1024
      const valid: File[] = []

      for (const file of Array.from(newFiles)) {
        if (files.length + valid.length >= maxFiles) {
          setError(`Maximum ${maxFiles} file${maxFiles !== 1 ? 's' : ''}`)
          break
        }
        if (file.size > maxBytes) {
          setError(`File too large (max ${maxSizeMb}MB): ${file.name}`)
          continue
        }
        valid.push(file)
      }

      const next = [...files, ...valid]
      setFiles(next)
      onFilesChange?.(next)
    },
    [files, maxFiles, maxSizeMb, onFilesChange],
  )

  const removeFile = useCallback(
    (index: number) => {
      const next = files.filter((_, i) => i !== index)
      setFiles(next)
      onFilesChange?.(next)
    },
    [files, onFilesChange],
  )

  return (
    <div className={cn('space-y-2', className)}>
      {/* Drop zone */}
      <button
        type="button"
        className={cn(
          'relative w-full rounded-xl border-2 border-dashed p-6 text-center transition-colors cursor-pointer',
          dragging
            ? 'border-primary bg-primary/5'
            : 'border-border/60 bg-muted/20 hover:bg-muted/40',
        )}
        onClick={() => inputRef.current?.click()}
        onDragOver={(e) => { e.preventDefault(); setDragging(true) }}
        onDragLeave={() => setDragging(false)}
        onDrop={(e) => {
          e.preventDefault()
          setDragging(false)
          addFiles(e.dataTransfer.files)
        }}
        aria-label={label}
      >
        <div className="flex flex-col items-center gap-2">
          <Upload className="h-6 w-6 text-muted-foreground" aria-hidden="true" />
          <p className="text-sm font-medium">{label}</p>
          <p className="text-xs text-muted-foreground">{hint}</p>
        </div>
      </button>

      {/* Hidden file input — capture="environment" for mobile camera */}
      <input
        ref={inputRef}
        type="file"
        accept={accept}
        multiple={maxFiles > 1}
        capture="environment"
        className="sr-only"
        aria-hidden="true"
        onChange={(e) => addFiles(e.target.files)}
      />

      {/* Error */}
      {error && <p className="text-xs text-destructive">{error}</p>}

      {/* File preview list */}
      {files.length > 0 && (
        <div className="space-y-1.5">
          {files.map((file, i) => (
            <div
              key={`${file.name}-${i}`}
              className="flex items-center gap-2 rounded-lg border border-border/60 px-3 py-2 bg-muted/20"
            >
              <ImageIcon className="h-4 w-4 text-muted-foreground shrink-0" />
              <span className="text-xs text-foreground truncate flex-1">{file.name}</span>
              <span className="text-xs text-muted-foreground tabular-nums shrink-0">
                {(file.size / (1024 * 1024)).toFixed(1)}MB
              </span>
              <button
                type="button"
                className="h-5 w-5 flex items-center justify-center text-muted-foreground hover:text-foreground shrink-0"
                onClick={() => removeFile(i)}
                aria-label={`Remove ${file.name}`}
              >
                <X className="h-3.5 w-3.5" />
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

