-- Sprint 7: Add status_history JSONB column to bookings table
-- Tracks all status transitions with actor and timestamp
-- Used by AppointmentTimeline + AppointmentDetailDrawer components

-- Add column (safe with default null — no backfill needed for existing rows)
ALTER TABLE bookings
  ADD COLUMN IF NOT EXISTS status_history JSONB DEFAULT '[]'::jsonb NOT NULL;

-- GIN index for JSONB querying (e.g. audit searches)
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_bookings_status_history
  ON bookings USING GIN (status_history);

-- Trigger function: appends a history entry whenever booking status changes
CREATE OR REPLACE FUNCTION append_booking_status_history()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  actor_id TEXT;
  entry JSONB;
BEGIN
  -- Only fire when status actually changes
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN
    RETURN NEW;
  END IF;

  -- Resolve actor: use auth.uid() if available, else 'system'
  actor_id := COALESCE(auth.uid()::text, 'system');

  entry := jsonb_build_object(
    'from', OLD.status::text,
    'to',   NEW.status::text,
    'at',   NOW()::text,
    'by',   actor_id
  );

  NEW.status_history := COALESCE(NEW.status_history, '[]'::jsonb) || jsonb_build_array(entry);

  RETURN NEW;
END;
$$;

-- Attach trigger to bookings table (replace if exists to make migration idempotent)
DROP TRIGGER IF EXISTS trg_bookings_status_history ON bookings;

CREATE TRIGGER trg_bookings_status_history
  BEFORE UPDATE OF status
  ON bookings
  FOR EACH ROW
  EXECUTE FUNCTION append_booking_status_history();

-- RLS note: status_history is readable via existing bookings RLS policies
-- (studio members can read bookings in their studio).
-- status_history is never directly writable by client — only the trigger writes to it.
-- Grant no additional permissions.

/**
 * SMS message templates for InkOS.
 *
 * All templates return plain-text strings (SMS has no HTML).
 * Max 160 chars per segment — keep messages short.
 * Emojis are intentionally avoided to ensure GSM-7 encoding and single segments.
 *
 * Usage:
 *   import { smsTemplates } from '@/lib/sms/templates'
 *   const body = smsTemplates.bookingConfirmation({ ... })
 *   await sendSms({ to: phone, body })
 */

export interface BookingConfirmationSmsData {
  clientFirstName: string
  studioName: string
  serviceName: string
  artistName: string
  scheduledAt: Date
  bookingReference: string
}

export interface ReminderSmsData {
  clientFirstName: string
  studioName: string
  serviceName: string
  artistName: string
  scheduledAt: Date
  hoursUntil: number
}

export interface DepositReceiptSmsData {
  clientFirstName: string
  studioName: string
  depositAmount: string
  bookingReference: string
}

export interface CancellationSmsData {
  clientFirstName: string
  studioName: string
  serviceName: string
  scheduledAt: Date
  reason?: string
}

function formatSmsDate(date: Date): string {
  return date.toLocaleDateString('en-US', {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  })
}

export const smsTemplates = {
  /**
   * Sent when a new booking is created (public flow or internal).
   * ~140 chars typical.
   */
  bookingConfirmation(data: BookingConfirmationSmsData): string {
    return (
      `Hi ${data.clientFirstName}, your ${data.serviceName} booking with ` +
      `${data.artistName} at ${data.studioName} is confirmed for ` +
      `${formatSmsDate(data.scheduledAt)}. Ref: ${data.bookingReference}`
    )
  },

  /**
   * Reminder sent 24h before the appointment.
   * ~120 chars typical.
   */
  reminder24h(data: ReminderSmsData): string {
    return (
      `Reminder: Your ${data.serviceName} with ${data.artistName} ` +
      `at ${data.studioName} is tomorrow at ` +
      `${formatSmsDate(data.scheduledAt)}. See you then!`
    )
  },

  /**
   * Reminder sent 2h before the appointment.
   * ~110 chars typical.
   */
  reminder2h(data: ReminderSmsData): string {
    return (
      `Heads up! Your ${data.serviceName} with ${data.artistName} ` +
      `at ${data.studioName} starts in 2 hours ` +
      `(${formatSmsDate(data.scheduledAt)}).`
    )
  },

  /**
   * Sent when a deposit payment is received.
   * ~100 chars typical.
   */
  depositReceipt(data: DepositReceiptSmsData): string {
    return (
      `Deposit of ${data.depositAmount} received for booking ${data.bookingReference} ` +
      `at ${data.studioName}. You're all set!`
    )
  },

  /**
   * Sent when a booking is cancelled by the studio.
   * ~120 chars typical.
   */
  cancellation(data: CancellationSmsData): string {
    const reasonPart = data.reason ? ` Reason: ${data.reason}.` : ''
    return (
      `Hi ${data.clientFirstName}, your ${data.serviceName} on ` +
      `${formatSmsDate(data.scheduledAt)} at ${data.studioName} ` +
      `has been cancelled.${reasonPart}`
    )
  },
} as const

/**
 * Booking Confirmation Email
 * Sent when: a new booking is created (internal or public flow)
 * Recipient: client
 */

import { Text, Section, Hr } from '@react-email/components'
import { BaseEmail, colors } from './_base'

export interface BookingConfirmationEmailProps {
  studioName: string
  clientFirstName: string
  serviceName: string
  artistName: string
  scheduledAt: Date
  endAt: Date
  durationMin: number
  priceCents: number
  depositCents: number
  depositPaid: boolean
  bookingReference: string
  depositPaymentUrl?: string
}

function formatDate(date: Date): string {
  return date.toLocaleDateString('en-US', {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
    year: 'numeric',
  })
}

function formatTime(date: Date): string {
  return date.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' })
}

function formatCurrency(cents: number): string {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(cents / 100)
}

export function BookingConfirmationEmail({
  studioName,
  clientFirstName,
  serviceName,
  artistName,
  scheduledAt,
  endAt,
  durationMin,
  priceCents,
  depositCents,
  depositPaid,
  bookingReference,
  depositPaymentUrl,
}: BookingConfirmationEmailProps) {
  const preview = `Your ${serviceName} booking is confirmed — ${formatDate(scheduledAt)}`

  return (
    <BaseEmail preview={preview} studioName={studioName}>
      {/* Heading */}
      <Text style={{ color: colors.text, fontSize: '22px', fontWeight: '600', margin: '0 0 8px' }}>
        You&apos;re booked, {clientFirstName}!
      </Text>
      <Text style={{ color: colors.textMuted, fontSize: '14px', margin: '0 0 24px' }}>
        Here&apos;s everything you need to know about your upcoming appointment.
      </Text>

      <Hr style={{ borderColor: colors.border, margin: '0 0 20px' }} />

      {/* Appointment details */}
      <Section style={{ marginBottom: '20px' }}>
        <Row label="Service" value={serviceName} />
        <Row label="Artist" value={artistName} />
        <Row label="Date" value={formatDate(scheduledAt)} />
        <Row
          label="Time"
          value={`${formatTime(scheduledAt)} – ${formatTime(endAt)} (${durationMin} min)`}
        />
        <Row label="Total" value={formatCurrency(priceCents)} />
        {depositCents > 0 && (
          <Row
            label="Deposit"
            value={depositPaid ? `${formatCurrency(depositCents)} — Paid` : `${formatCurrency(depositCents)} — Due`}
          />
        )}
      </Section>

      <Hr style={{ borderColor: colors.border, margin: '0 0 20px' }} />

      {/* Deposit CTA */}
      {depositCents > 0 && !depositPaid && depositPaymentUrl && (
        <Section style={{ textAlign: 'center', margin: '0 0 20px' }}>
          <Text style={{ color: colors.textMuted, fontSize: '13px', margin: '0 0 12px' }}>
            Your booking requires a deposit of {formatCurrency(depositCents)} to be secured.
          </Text>
          <a
            href={depositPaymentUrl}
            style={{
              display: 'inline-block',
              backgroundColor: colors.primary,
              color: '#ffffff',
              borderRadius: '8px',
              padding: '10px 24px',
              fontSize: '14px',
              fontWeight: '600',
              textDecoration: 'none',
            }}
          >
            Pay deposit — {formatCurrency(depositCents)}
          </a>
        </Section>
      )}

      {/* Reference */}
      <Text style={{ color: colors.textMuted, fontSize: '12px', margin: '0', fontFamily: 'monospace' }}>
        Booking reference: {bookingReference}
      </Text>
    </BaseEmail>
  )
}

function Row({ label, value }: { label: string; value: string }) {
  return (
    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
      <Text style={{ color: colors.textMuted, fontSize: '13px', margin: '0', minWidth: '100px' }}>
        {label}
      </Text>
      <Text style={{ color: colors.text, fontSize: '13px', margin: '0', fontWeight: '500', textAlign: 'right' }}>
        {value}
      </Text>
    </div>
  )
}

export default BookingConfirmationEmail

/**
